#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  int r;  } Queue_LedTest;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~SQueue* qu = NULL;void CALLBACK TimerProc(HWND hwnd, UINT uMsg, UINT_PTR idEvent, DWORD dwTime )  {  if ( qu != NULL )    {    qu->nLedTest--;    if ( qu->nLedTest == 0 )      {      qu = NULL;      ::KillTimer( hwnd, 1234 );      }    ::InvalidateRect( hwnd, NULL, FALSE );    }  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~int PressLedTest(DefinePress)  {  //  if ( nCode == 0 )    return 0;  //  else  if ( nCode == 1 )    return 0;  //  Queue_LedTest* p = (Queue_LedTest*)s;  if ( !::PtInRect( &p->mRect, point ) )    return 0;  //  q.nLedTest = p->r;  qu = &q;  ::SetTimer( q.hWnd, 1234, 100, TimerProc );  //  return 0;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintLedTest(DefinePaint)  {  QueueP(Queue_LedTest);  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddLedTest(DefineTegs)  {  AddQueueEx(Queue_LedTest);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintLedTest;  p->press = &PressLedTest;  //  STegObj obj[] =    {    { 'R', "rect", &p->mRect },    { 'E', "rc"  , &p->mRect },    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  p->r = Atoi(teg[0].value);  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~